<template><div class="dash-stack"><div class="dash-toolbar"><div><h2>Assigned-area land records</h2><p>Search records by a recorded owner's email.</p></div><div class="toolbar-actions"><span class="draft-shortcut"><IconButton icon="draft-updates" label="Draft updates" @click="$router.push('/dashboard/landofficer/drafts/updates')"/><b>{{drafts.updates||0}}</b></span><span class="draft-shortcut"><IconButton icon="draft-creates" label="Draft creates" @click="$router.push('/dashboard/landofficer/drafts/creates')"/><b>{{drafts.creates||0}}</b></span><IconButton icon="add" label="Create land record" @click="startDraft" :disabled="!hasArea"/></div></div><div class="glass-panel"><div class="table-tools"><div class="search-box"><span>⌕</span><input v-model="ownerEmail" placeholder="Search owner email" @input="load(1)"/></div><span class="muted">{{result.totalCount||0}} records</span></div><div v-if="!hasArea" class="state-message">No area is assigned to your officer account yet. Contact an administrator.</div><div v-else-if="loading" class="state-message">Loading land records…</div><div v-else-if="!result.items?.length" class="state-message">No land records found in your assigned area.</div><div v-else class="record-grid"><article v-for="land in result.items" :key="land.landId" class="record-card"><div class="record-top"><span class="record-label">LAND ID</span><span class="status-tag">{{land.overallStatus||'Not assessed'}}</span></div><h3>{{land.landId}}</h3><p>{{land.area?.mouza}}, {{land.area?.upazila}}, {{land.area?.district}}</p><div class="record-meta"><span>Dag {{land.dagNo}}</span><span>{{land.recordType}}</span></div><div class="record-owner-preview">{{(land.owners||[]).map((o)=>o.ownerEmail).join(' · ')||'No owners recorded'}}</div><div v-if="land.hasUpdateDraft" class="draft-in-progress">Draft in progress</div><div class="record-actions"><IconButton :icon="expandedId===land.landId?'collapse':'expand'" :label="expandedId===land.landId?'Collapse details':'View more details'" @click="expandedId=expandedId===land.landId?null:land.landId"/><IconButton icon="edit" label="Edit land record" @click="editLand(land)"/></div><LandDetailsPanel v-if="expandedId===land.landId" :land="land"/></article></div><div class="pagination"><span>Page {{result.page||1}} of {{result.totalPages||0}}</span><div><IconButton icon="previous" label="Previous page" :disabled="!result.hasPrevious" @click="load((result.page||1)-1)"/><IconButton icon="next" label="Next page" :disabled="!result.hasNext" @click="load((result.page||1)+1)"/></div></div></div></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useStore}from'vuex';import{useRouter}from'vue-router';import{platformApi}from'@/services/platform';import IconButton from'@/components/ui/IconButton.vue';import LandDetailsPanel from'@/components/ui/LandDetailsPanel.vue';const store=useStore(),router=useRouter(),user=computed(()=>store.getters['auth/user']),hasArea=computed(()=>!!user.value?.assignedAreaId),result=ref<any>({items:[]}),drafts=ref<any>({}),loading=ref(false),ownerEmail=ref(''),expandedId=ref<string|null>(null);async function load(page=1){loading.value=true;try{result.value=(await platformApi.officerLands(page,ownerEmail.value)).data}catch{}finally{loading.value=false}}async function refreshDrafts(){try{drafts.value=(await platformApi.draftSummary()).data}catch{}}function startDraft(){router.push('/dashboard/landofficer/drafts/creates/new')}function editLand(land:any){router.push({path:'/dashboard/landofficer/drafts/updates/'+land.landId})}onMounted(()=>{load();refreshDrafts()});</script>
